// Snippy users for PocketBase.
// This handles username generation and validation.

/// <reference path="../pb_data/types.d.ts" />

// Generate a unique username for a user.
onRecordCreate((e) => {
  const lib = require(`${__hooks}/lib.js`);
  const preferred = e.record.getString('username');
  if (
    !preferred ||
    !lib.isValidUsername(preferred) ||
    lib.isAutogeneratedUsername(preferred)
  ) {
    e.record.set('username', lib.uniqueUsername(e.app, e.record.getString('name'), ''));
  } else if (lib.usernameTaken(e.app, preferred, e.record.id || '')) {
    e.record.set('username', lib.uniqueUsername(e.app, preferred, e.record.id || ''));
  }
  if (!e.record.getString('name')) {
    e.record.set('name', e.record.getString('username'));
  }
  const priv = e.record.get('isPrivate');
  if (priv === null || priv === undefined) {
    e.record.set('isPrivate', false);
  }
  e.next();
}, 'users');

// Validate a username on update.
onRecordUpdateRequest((e) => {
  const lib = require(`${__hooks}/lib.js`);
  const name = e.record.getString('username');
  if (lib.isReservedUsername(name)) {
    throw new BadRequestError('That username is reserved');
  }
  if (lib.usernameTaken(e.app, name, e.record.id)) {
    throw new BadRequestError('Username is taken');
  }
  const bio = e.record.getString('bio');
  if (bio && bio.length > 500) {
    throw new BadRequestError('Bio is too long');
  }
  const prefs = e.record.get('editorPreferences');
  if (prefs && JSON.stringify(prefs).length > 8000) {
    throw new BadRequestError('Editor preferences are too large');
  }
  if (e.record.get('isPrivate') === null || e.record.get('isPrivate') === undefined) {
    e.record.set('isPrivate', false);
  }
  e.next();
}, 'users');

// Editor preferences stay on the signed-in user's own record.
onRecordEnrich((e) => {
  const info = e.requestInfo;
  const auth = info ? info.auth : null;
  let superuser = false;
  try {
    superuser = !!(auth && auth.collection().name === '_superusers');
  } catch (err) {
    superuser = false;
  }
  if (!superuser && (!auth || auth.id !== e.record.id)) {
    e.record.hide('editorPreferences');
  }
  e.next();
}, 'users');
